package vn.rtr.aeris.field02;
import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import sun.misc.Unsafe;
/** Calls the exact frozen Activity admission method without running Android or its constructor. */
public class Quota02Test {
 static int checks=0;static class BudgetFile extends File{final long free;BudgetFile(String path,long n){super(path);free=n;}@Override public long getUsableSpace(){return free;}}
 static void set(Object a,String key,Object value)throws Exception{Field f=ShellActivity.class.getDeclaredField(key);f.setAccessible(true);f.set(a,value);}
 static void call(Object a,int more,boolean allowed)throws Exception{Method m=ShellActivity.class.getDeclaredMethod("admission",int.class);m.setAccessible(true);try{m.invoke(a,more);if(!allowed)throw new AssertionError("must refuse");}catch(InvocationTargetException e){if(allowed||!(e.getCause() instanceof IOException)||!e.getCause().getMessage().equals("LOCAL_QUOTA_RESERVE_NO_AUTO_DELETE"))throw e;}checks++;}
 public static void main(String[]args)throws Exception{File root=new File(args[0]);if(!root.mkdir())throw new IOException("EXCLUSIVE_TEST_ROOT");Field f=Unsafe.class.getDeclaredField("theUnsafe");f.setAccessible(true);Object a=((Unsafe)f.get(null)).allocateInstance(ShellActivity.class);set(a,"root",new BudgetFile(root.toString(),Integrity02.RESERVE+1024));set(a,"operations",15);call(a,0,true);set(a,"operations",16);call(a,0,false);set(a,"operations",0);set(a,"root",new BudgetFile(root.toString(),Integrity02.RESERVE-1));call(a,0,false);set(a,"root",new BudgetFile(root.toString(),Integrity02.RESERVE+1024));call(a,1024,true);call(a,1025,false);set(a,"root",new BudgetFile(root.toString(),Long.MAX_VALUE));File data=new File(root,"retained.bin");byte[]b="must never delete".getBytes("UTF-8");Files.write(data.toPath(),b);call(a,(int)Integrity02.QUOTA,false);if(!java.util.Arrays.equals(b,Files.readAllBytes(data.toPath())))throw new AssertionError("original changed");checks++;System.out.println("{\"status\":\"PASS\",\"checks\":"+checks+",\"scope\":\"EXACT_FROZEN_NATIVE_ADMISSION_METHOD_HOST_JVM_WITH_ANDROID_STUBS_NOT_ART\"}");}
}
